type Fetch = typeof fetch

export type AdapterReqOptions = {
  url: string
  method?: string
  headers?: Record<string, string>
  body?: unknown
  data?: unknown
  signal?: AbortSignal
  timeout?: number
  shouldThrowOnError?: boolean
}

export type AdapterReqInstance = {
  fetch: (options: AdapterReqOptions) => Promise<unknown>
}

export type AdapterReqClass = new (config?: Record<string, unknown>) => AdapterReqInstance

function headersToObject(headers?: HeadersInit): Record<string, string> {
  if (!headers) {
    return {}
  }
  if (typeof Headers !== 'undefined' && headers instanceof Headers) {
    const obj: Record<string, string> = {}
    headers.forEach((value, key) => {
      obj[key] = value
    })
    return obj
  }
  if (Array.isArray(headers)) {
    const obj: Record<string, string> = {}
    for (const [key, value] of headers) {
      obj[key] = String(value)
    }
    return obj
  }
  const obj: Record<string, string> = {}
  for (const [key, value] of Object.entries(headers as Record<string, unknown>)) {
    if (value != null) {
      obj[key] = String(value)
    }
  }
  return obj
}

function resolveUrl(input: RequestInfo | URL): string {
  if (typeof input === 'string') {
    return input
  }
  if (typeof URL !== 'undefined' && input instanceof URL) {
    return input.toString()
  }
  if (typeof Request !== 'undefined' && input instanceof Request) {
    return input.url
  }
  return String((input as { url?: string }).url ?? input)
}

async function parseBody(data: unknown): Promise<unknown> {
  const value = await data
  if (value == null || value === '') {
    return {}
  }
  if (typeof value === 'string') {
    try {
      return JSON.parse(value)
    } catch {
      return { message: value }
    }
  }
  return value
}

function toResponseLike(result: unknown): Response {
  if (
    result &&
    typeof result === 'object' &&
    typeof (result as Response).status === 'number' &&
    typeof (result as Response).json === 'function'
  ) {
    return result as Response
  }

  const raw = (result ?? {}) as {
    statusCode?: number
    status?: number
    statusMessage?: string
    statusText?: string
    errMsg?: string
    header?: unknown
    headers?: unknown
    data?: unknown
  }

  const status = raw.statusCode ?? raw.status ?? 0
  const data = raw.data

  return {
    ok: status >= 200 && status < 300,
    status,
    statusText: raw.statusMessage || raw.statusText || raw.errMsg || '',
    headers: raw.header ?? raw.headers ?? {},
    json: async () => parseBody(data),
    text: async () => {
      const value = await data
      if (typeof value === 'string') {
        return value
      }
      if (value == null) {
        return ''
      }
      return JSON.stringify(value)
    },
  } as Response
}

/**
 * Wrap CloudBase `adapter.reqClass` (WxRequest / WebRequest / NodeRequest) as
 * a standard `fetch(url, init)`. Do not import platform adapters here — the
 * host passes the class after `useAdapters`.
 *
 * `httpSend()` already sets `apikey` / `Authorization`; this talks to the raw
 * adapter so CloudBase request hooks do not inject a second auth header.
 */
export function wrapReqClassFetch(
  ReqClass: AdapterReqClass,
  config: Record<string, unknown> = {}
): Fetch {
  const req = new ReqClass(config)
  return async (input, init = {}) => {
    const result = await req.fetch({
      url: resolveUrl(input),
      method: init.method || 'GET',
      headers: headersToObject(init.headers),
      body: init.body,
      data: init.body,
      signal: init.signal ?? undefined,
      shouldThrowOnError: false,
    })
    return toResponseLike(result)
  }
}
